function pair(r: V2BacktestResult) {
  const open = new Map<string, TradeEntry[]>();
  const out: C[] = [];
  for (const t of r.tradeLog) {
    if (t.strategyTag !== 'QQQ_EQUITY_BOOST_PUT_SPREAD') continue;
    const key = `${t.symbol}|${t.expiry ?? ''}`;
    if (t.action === 'OPEN') { const a = open.get(key) ?? []; a.push(t); open.set(key, a); continue; }
    if (t.action !== 'CLOSE' && t.action !== 'SETTLE') continue;
    if (!Number.isFinite(t.pnl)) continue;
    const o = open.get(key)?.shift();
    if (o) out.push({ open: o, close: t, pnl: t.pnl! });
  }
  return out.sort((a, b) => date(a.open).localeCompare(date(b.open)));
}

function metrics(c: C[]) {
  const p = c.map(x => x.pnl), wins = p.filter(x => x > 0).length, sorted = [...p].sort((a, b) => a - b);
  const k = p.length ? Math.max(1, Math.ceil(p.length * .05)) : 0;
  let equity = 0, peak = 0, mdd = 0;
  for (const x of p) { equity += x; peak = Math.max(peak, equity); mdd = Math.max(mdd, peak - equity); }
  return { n: p.length, wins, losses: p.length - wins, winRate: p.length ? wins / p.length : null,
    pnl: p.reduce((a, x) => a + x, 0), mdd,
    cvar5: k ? sorted.slice(0, k).reduce((a, x) => a + x, 0) / k : null, worst: sorted[0] ?? null };
}

